-KEYCLOAK_BASE_URL="http://localhost:8080/auth"
-KEYCLOAK_REALM="master"
-KEYCLOAK_URL="${KEYCLOAK_BASE_URL}/realms/${KEYCLOAK_REALM}"
-
-KEYCLOAK_CLIENT_ID="admin"
-KEYCLOAK_CLIENT_SECRET="admin"
-
